"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { type FormEvent, useEffect, useId, useState } from "react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";

import { BlockFrame } from "../parts/block-frame";
import { SparklesIcon } from "../parts/icons";
import { person } from "./shared/people";
import { AvailabilityStrips } from "./smart-scheduler/availability-strips";
import { ORGANISER, type Reading, readRequest, suggest, type Suggestion, weekDays } from "./smart-scheduler/data";
import { InviteDraft } from "./smart-scheduler/invite-draft";
import { SuggestionList } from "./smart-scheduler/suggestion-list";

type Phase = "idle" | "reading" | "checking" | "ready" | "invite";

const START_TEXT = "45 minutes with Noor and Kofi next week, in the morning";

/** The chips for what was read from a request, in the order they appear. */
function chipsFor(reading: Reading) {
  const names = reading.people.map((id) => person(id).name.split(" ")[0]).join(" and ");
  return [
    `${reading.minutes} minutes`,
    `You, ${names}`,
    reading.week === "this" ? "This week" : "Next week",
    reading.part === "any" ? "Any time of day" : reading.part === "morning" ? "Mornings" : "Afternoons",
  ];
}

/**
 * Finds a meeting time from one plain sentence. The sentence is read into
 * chips, the calendars are checked, and three ranked times come back, each
 * with a reason. The strips show who is busy around the time in focus. Picking
 * a time opens a draft invite ready to send.
 */
export function SmartScheduler({ className }: { className?: string }) {
  const [text, setText] = useState(START_TEXT);
  const [phase, setPhase] = useState<Phase>("idle");
  const [reading, setReading] = useState<Reading | null>(null);
  const [suggestions, setSuggestions] = useState<Suggestion[]>([]);
  const [selected, setSelected] = useState(0);
  const reduceMotion = useReducedMotion();
  const titleId = useId();
  const fieldId = useId();

  useEffect(() => {
    if (phase !== "reading" && phase !== "checking") return;
    const timer = window.setTimeout(
      () => {
        if (phase === "reading") setPhase("checking");
        else {
          if (reading) setSuggestions(suggest(reading));
          setSelected(0);
          setPhase("ready");
        }
      },
      phase === "reading" ? 600 : 700,
    );
    return () => window.clearTimeout(timer);
  }, [phase, reading]);

  const find = (event: FormEvent) => {
    event.preventDefault();
    if (!text.trim()) return;
    setReading(readRequest(text));
    setSuggestions([]);
    setPhase("reading");
  };

  const busy = phase === "reading" || phase === "checking";
  const people = reading ? [ORGANISER, ...reading.people] : [];
  const days = reading ? weekDays(reading.week) : [];
  const focus = suggestions[selected];

  return (
    <BlockFrame aria-labelledby={titleId} className={cn("max-w-2xl", className)}>
      <form onSubmit={find} className="flex flex-col gap-3 border-b border-border px-5 py-4">
        <h2 id={titleId} className="text-base font-semibold">
          Find a time
        </h2>
        <div className="flex flex-wrap gap-2">
          <label htmlFor={fieldId} className="sr-only">
            Describe the meeting
          </label>
          <Input
            id={fieldId}
            value={text}
            onChange={(event) => setText(event.target.value)}
            placeholder="30 minutes with Lena this week, afternoons"
            className="min-w-0 flex-1 basis-60"
          />
          <Button type="submit" disabled={busy || !text.trim()}>
            <SparklesIcon />
            Find times
          </Button>
        </div>
        <div className="flex min-h-7 flex-wrap items-center gap-1.5" aria-live="polite">
          {busy ? (
            <span className="text-xs text-muted-foreground motion-safe:animate-pulse">
              {phase === "reading" ? "Reading your request" : `Checking ${people.length} calendars`}
            </span>
          ) : null}
          {reading && phase !== "reading"
            ? chipsFor(reading).map((chip, index) => (
                <motion.span
                  key={`${chip}-${index}`}
                  initial={reduceMotion ? false : { opacity: 0, y: 4 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: reduceMotion ? 0 : index * 0.06, duration: 0.2 }}
                  className="inline-flex items-center gap-1 rounded-full border border-border px-2 py-0.5 text-xs"
                >
                  {index === 0 ? <SparklesIcon aria-hidden="true" className="size-3 text-chart-1" /> : null}
                  {chip}
                </motion.span>
              ))
            : null}
        </div>
      </form>

      <div className="flex flex-col gap-4 px-5 py-4">
        <AnimatePresence mode="wait" initial={false}>
          {phase === "idle" ? (
            <p key="idle" className="py-6 text-center text-sm text-muted-foreground">
              Say who, how long and roughly when. Press Enter to find times.
            </p>
          ) : phase === "invite" && focus ? (
            <motion.div key="invite" initial={reduceMotion ? false : { opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }}>
              <InviteDraft suggestion={focus} dayLabel={days[focus.day] ?? ""} people={people} onBack={() => setPhase("ready")} />
            </motion.div>
          ) : (
            <motion.div key="results" className="flex flex-col gap-4" initial={false} animate={{ opacity: busy ? 0.5 : 1 }}>
              {focus ? (
                <>
                  <AvailabilityStrips people={people} focus={focus} dayLabel={days[focus.day] ?? ""} />
                  <SuggestionList
                    suggestions={suggestions}
                    days={days}
                    selected={selected}
                    onSelect={setSelected}
                    onPick={(index) => {
                      setSelected(index);
                      setPhase("invite");
                    }}
                  />
                  <div className="flex justify-end">
                    <Button onClick={() => setPhase("invite")} disabled={busy}>
                      Draft invite
                    </Button>
                  </div>
                </>
              ) : (
                <p className="py-6 text-center text-sm text-muted-foreground">Looking across the week…</p>
              )}
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </BlockFrame>
  );
}

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

