/** A speech bubble, from the chosen icon pack. */
export const MessageIcon = packIcon("message");
/** A play mark, from the chosen icon pack. */
export const PlayerPlayFilledIcon = packIcon("play");
/** A plus, from the chosen icon pack. */
export const PlusIcon = packIcon("plus");
/** A refresh mark, from the chosen icon pack. */
export const RefreshIcon = packIcon("refresh");
/** Sparkles, from the chosen icon pack. */
export const SparklesIcon = packIcon("sparkles");
/** Two people, from the chosen icon pack. */
export const UsersIcon = packIcon("users");
/** A close mark, from the chosen icon pack. */
export const XIcon = packIcon("x");

/** Two arrows that cross, for swapping two things. */
export const ArrowsShuffleIcon = ownIcon(
  <>
    <path d="M2 4.5h2.2c1.2 0 2.3.6 3 1.6l1.6 3.8c.7 1 1.8 1.6 3 1.6H14" />
    <path d="M2 11.5h2.2c1 0 1.9-.4 2.6-1.1M9.2 5.6c.7-.7 1.6-1.1 2.6-1.1H14" />
    <path d="M12 2.5l2 2-2 2M12 9.5l2 2-2 2" />
  </>,
);

/** Six dots, for a handle a person drags. */
export const GripVerticalIcon = ownIcon(
  <path d="M6 3.5h.01M10 3.5h.01M6 8h.01M10 8h.01M6 12.5h.01M10 12.5h.01" strokeWidth="2" />,
);

/** Two bars, for pause. */
export const PlayerPauseFilledIcon = ownIcon(<path d="M5.5 3.5v9M10.5 3.5v9" strokeWidth="2.5" />);

/** A bin, for remove. */
export const TrashIcon = ownIcon(
  <>
    <path d="M2.5 4.5h11M6 4.5V3a.5.5 0 0 1 .5-.5h3A.5.5 0 0 1 10 3v1.5" />
    <path d="M4 4.5l.6 8a1 1 0 0 0 1 .9h4.8a1 1 0 0 0 1-.9l.6-8M6.75 7v4M9.25 7v4" />
  </>,
);

/** The five chart hues, in order. A person or a calendar takes one by index. */
export type Hue = 1 | 2 | 3 | 4 | 5;

/** One member of the Fernhill team, used across the project blocks. */
export interface Person {
  id: string;
  name: string;
  initials: string;
  hue: Hue;
}

/** The Fernhill team. Every block draws its owners, attendees and authors from this list. */
export const TEAM: Person[] = [
  { id: "ines", name: "Ines Varga", initials: "IV", hue: 1 },
  { id: "tomas", name: "Tomas Reyes", initials: "TR", hue: 2 },
  { id: "noor", name: "Noor Haddad", initials: "NH", hue: 3 },
  { id: "kofi", name: "Kofi Mensah", initials: "KM", hue: 4 },
  { id: "lena", name: "Lena Brandt", initials: "LB", hue: 5 },
  { id: "arjun", name: "Arjun Patel", initials: "AP", hue: 2 },
];

/** The person with this id. Unknown ids fall back to the first person, so sample data never renders blank. */
export function person(id: string): Person {
  return TEAM.find((member) => member.id === id) ?? TEAM[0]!;
}

/** A solid fill in each hue, for a bar, a dot or a marker. Written out so the class lint can read every name. */
export const HUE_FILL = {
  1: "bg-chart-1",
  2: "bg-chart-2",
  3: "bg-chart-3",
  4: "bg-chart-4",
  5: "bg-chart-5",
} satisfies Record<Hue, string>;

/** A border in each hue. */
export const HUE_BORDER = {
  1: "border-chart-1",
  2: "border-chart-2",
  3: "border-chart-3",
  4: "border-chart-4",
  5: "border-chart-5",
} satisfies Record<Hue, string>;

/** Text in each hue, for an icon or a small mark. Not for body text: a hue may not reach 4.5 to 1. */
export const HUE_TEXT = {
  1: "text-chart-1",
  2: "text-chart-2",
  3: "text-chart-3",
  4: "text-chart-4",
  5: "text-chart-5",
} satisfies Record<Hue, string>;

"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";

import { cn } from "@/lib/utils";

import { PersonAvatar } from "../shared/avatar";
import { HUE_FILL, person } from "../shared/people";
import { BUSY, STRIP_END, STRIP_START, type Suggestion } from "./data";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

const SPAN = STRIP_END - STRIP_START;
const pct = (minutes: number) => ((minutes - STRIP_START) / SPAN) * 100;
const AXIS = [8, 10, 12, 14, 16, 18];
const hourLabel = (hour: number) => (hour === 12 ? "12 pm" : hour > 12 ? `${hour - 12} pm` : `${hour} am`);

/** Props for the availability strips. */
export interface AvailabilityStripsProps {
  people: string[];
  /** The suggestion the person is looking at; its day and time are highlighted. */
  focus: Suggestion;
  dayLabel: string;
}

/**
 * One strip per person for the focused day: busy blocks in their hue on an
 * hour axis, and one highlighted column for the focused time that slides when
 * the focus moves. Blocks crossfade when the day changes.
 */
export function AvailabilityStrips({ people, focus, dayLabel }: AvailabilityStripsProps) {
  const reduceMotion = useReducedMotion();
  const spring = reduceMotion ? { duration: 0 } : { type: "spring" as const, stiffness: 400, damping: 40 };
  return (
    <figure className="flex flex-col gap-2" aria-label={`Who is busy on ${dayLabel}`}>
      <figcaption className="text-xs text-muted-foreground">{dayLabel}</figcaption>
      <div className="relative flex flex-col gap-1.5">
        {people.map((id) => {
          const member = person(id);
          const blocks = (BUSY.get(id) ?? []).filter((busy) => busy.day === focus.day);
          return (
            <div key={id} className="flex items-center gap-2">
              <span className="flex w-20 shrink-0 items-center gap-1.5 text-xs">
                <PersonAvatar person={member} />
                {member.name.split(" ")[0]}
              </span>
              <div className="relative h-5 flex-1 overflow-hidden rounded-md">
                <span aria-hidden="true" className="absolute inset-0 bg-muted-foreground/15" />
                <AnimatePresence initial={false}>
                  {blocks.map((busy) => (
                    <motion.span
                      key={`${busy.day}-${busy.start}`}
                      initial={{ opacity: 0 }}
                      animate={{ opacity: 0.85 }}
                      exit={{ opacity: 0 }}
                      transition={{ duration: reduceMotion ? 0 : 0.2 }}
                      title={busy.what}
                      className={cn("left-(--left) w-(--width) absolute inset-y-0.5 rounded-sm", HUE_FILL[member.hue])}
                      style={
                        // SAFETY: the keys are CSS custom properties, which CSSProperties does not list.
                        { "--left": `${pct(busy.start)}%`, "--width": `${pct(busy.end) - pct(busy.start)}%` } as VarStyle
                      }
                    />
                  ))}
                </AnimatePresence>
                <span className="sr-only">
                  {blocks.length === 0 ? "Free all day" : `Busy: ${blocks.map((busy) => busy.what).join(", ")}`}
                </span>
              </div>
            </div>
          );
        })}
        <div aria-hidden="true" className="pointer-events-none absolute inset-y-0 right-0 left-22">
          <motion.span
            className="absolute -inset-y-1 rounded-md border-2 border-foreground/70"
            initial={false}
            animate={{ left: `${pct(focus.start)}%`, width: `${pct(focus.end) - pct(focus.start)}%` }}
            transition={spring}
          />
        </div>
      </div>
      <div aria-hidden="true" className="relative ml-22 h-4 text-xs text-muted-foreground">
        {AXIS.map((hour) => (
          <span key={hour} className="left-(--left) absolute -translate-x-1/2 tabular-nums" style={
            // SAFETY: the keys are CSS custom properties, which CSSProperties does not list.
            { "--left": `${pct(hour * 60)}%` } as VarStyle
          }>
            {hourLabel(hour)}
          </span>
        ))}
      </div>
    </figure>
  );
}

import { cn } from "@/lib/utils";

import { HUE_BORDER, HUE_FILL, type Person } from "./people";

/** Props for one person's initials badge. */
export interface PersonAvatarProps {
  person: Person;
  /** `sm` is 1.5rem, `md` is 2rem. */
  size?: "sm" | "md";
  /** Shows the name to screen readers. Leave it off when the name is already written beside the badge. */
  labelled?: boolean;
  className?: string;
}

/**
 * A round badge with a person's initials, ringed and tinted in their hue. The
 * tint is a faded layer behind the letters, so the letters keep full contrast.
 */
export function PersonAvatar({ person, size = "sm", labelled = false, className }: PersonAvatarProps) {
  return (
    <span
      role={labelled ? "img" : undefined}
      aria-label={labelled ? person.name : undefined}
      aria-hidden={labelled ? undefined : true}
      title={person.name}
      className={cn(
        "relative isolate inline-grid shrink-0 place-items-center overflow-hidden rounded-full border-2 bg-card font-semibold text-foreground",
        HUE_BORDER[person.hue],
        size === "sm" ? "size-7 text-xs tracking-tight" : "size-8 text-xs",
        className,
      )}
    >
      <span aria-hidden="true" className={cn("absolute inset-0 -z-10 opacity-25", HUE_FILL[person.hue])} />
      {person.initials}
    </span>
  );
}

/** Props for a row of overlapping initials badges. */
export interface AvatarStackProps {
  people: Person[];
  /** Badges past this count fold into a "+N" badge. */
  max?: number;
  size?: "sm" | "md";
  className?: string;
}

/** A row of overlapping initials badges, named as one group, such as the people on a project. */
export function AvatarStack({ people, max = 4, size = "sm", className }: AvatarStackProps) {
  const shown = people.slice(0, max);
  const rest = people.length - shown.length;
  return (
    <span
      role="img"
      aria-label={people.map((member) => member.name).join(", ")}
      className={cn("flex items-center -space-x-1.5", className)}
    >
      {shown.map((member) => (
        <PersonAvatar key={member.id} person={member} size={size} className="ring-2 ring-card" />
      ))}
      {rest > 0 ? (
        <span
          aria-hidden="true"
          className={cn(
            "inline-grid shrink-0 place-items-center rounded-full border-2 border-border bg-card font-medium text-muted-foreground ring-2 ring-card",
            size === "sm" ? "size-7 text-xs tracking-tight" : "size-8 text-xs",
          )}
        >
          +{rest}
        </span>
      ) : null}
    </span>
  );
}

import { TEAM } from "../shared/people";

/** A busy stretch on one day, in minutes after midnight. */
export interface Busy {
  day: number;
  start: number;
  end: number;
  what: string;
}

/** The person booking: always invited. */
export const ORGANISER = "ines";

/** The weekdays of this week or next week, Monday to Friday. */
export const weekDays = (week: "this" | "next") =>
  week === "this"
    ? ["Mon, Nov 9", "Tue, Nov 10", "Wed, Nov 11", "Thu, Nov 12", "Fri, Nov 13"]
    : ["Mon, Nov 16", "Tue, Nov 17", "Wed, Nov 18", "Thu, Nov 19", "Fri, Nov 20"];

/** Where each strip starts, in minutes after midnight. */
export const STRIP_START = 8 * 60;
/** Where each strip ends, in minutes after midnight. */
export const STRIP_END = 18 * 60;

/** Each person's busy time next week. */
export const BUSY = new Map<string, Busy[]>(
  Object.entries({
  ines: [
    { day: 0, start: 540, end: 630, what: "Clinic rounds" },
    { day: 1, start: 600, end: 660, what: "Supplier call" },
    { day: 2, start: 480, end: 570, what: "Rota review" },
    { day: 3, start: 780, end: 900, what: "Home visits" },
    { day: 4, start: 540, end: 600, what: "Case review" },
  ],
  noor: [
    { day: 0, start: 480, end: 600, what: "Patient visits" },
    { day: 1, start: 540, end: 630, what: "Patient visits" },
    { day: 2, start: 630, end: 720, what: "Training" },
    { day: 3, start: 540, end: 660, what: "Patient visits" },
    { day: 4, start: 600, end: 690, what: "Patient visits" },
  ],
  kofi: [
    { day: 0, start: 630, end: 720, what: "Room audit" },
    { day: 1, start: 480, end: 570, what: "Visit" },
    { day: 1, start: 660, end: 720, what: "Visit" },
    { day: 2, start: 540, end: 630, what: "Visit" },
    { day: 3, start: 480, end: 600, what: "Visit" },
    { day: 4, start: 510, end: 630, what: "Visit" },
  ],
  lena: [
    { day: 0, start: 540, end: 600, what: "Release prep" },
    { day: 2, start: 570, end: 660, what: "Design review" },
    { day: 4, start: 660, end: 750, what: "Workshop" },
  ],
  tomas: [
    { day: 1, start: 600, end: 690, what: "Planning" },
    { day: 3, start: 540, end: 600, what: "Standup" },
  ],
  }),
);

/** What the scheduler read from a request. */
export interface Reading {
  minutes: number;
  people: string[];
  week: "this" | "next";
  part: "morning" | "afternoon" | "any";
}

/** Reads a plain request into a length, the people, the week and the part of day. Unread parts take sensible defaults. */
export function readRequest(text: string): Reading {
  const lower = text.toLowerCase();
  const hours = /(\d+(?:\.\d+)?)\s*(?:h|hr|hrs|hour|hours)\b/.exec(lower);
  const mins = /(\d+)\s*(?:m|min|mins|minutes)\b/.exec(lower);
  const minutes = mins ? Number(mins[1]) : hours ? Math.round(Number(hours[1]) * 60) : lower.includes("half an hour") ? 30 : 30;
  const people = TEAM.filter((member) => member.id !== ORGANISER && lower.includes(member.name.split(" ")[0]!.toLowerCase())).map(
    (member) => member.id,
  );
  return {
    minutes: Math.max(15, Math.min(180, minutes)),
    people: people.length > 0 ? people : ["noor"],
    week: lower.includes("this week") ? "this" : "next",
    part: lower.includes("morning") ? "morning" : lower.includes("afternoon") ? "afternoon" : "any",
  };
}

/** One suggested time, with why it was ranked where it is. */
export interface Suggestion {
  day: number;
  start: number;
  end: number;
  /** People who are busy then, with what they are doing. Empty for a clear slot. */
  conflicts: { id: string; what: string }[];
  reason: string;
}

const PART = { morning: [480, 720], afternoon: [780, 1080], any: [480, 1080] } as const;

/**
 * Finds the three best times: clear slots first, earliest in the week and
 * nearest the start of the window, then the slots with the fewest people busy.
 */
export function suggest(reading: Reading): Suggestion[] {
  const people = [ORGANISER, ...reading.people];
  const [from, to] = PART[reading.part];
  const options: Suggestion[] = [];
  for (let day = 0; day < 5; day += 1) {
    for (let start = from; start + reading.minutes <= to; start += 30) {
      const end = start + reading.minutes;
      const conflicts = people.flatMap((id) =>
        (BUSY.get(id) ?? []).filter((busy) => busy.day === day && busy.start < end && busy.end > start).map((busy) => ({ id, what: busy.what })),
      );
      options.push({ day, start, end, conflicts, reason: "" });
    }
  }
  const ranked = options.sort((a, b) => a.conflicts.length - b.conflicts.length || a.day - b.day || a.start - b.start);
  const picked: Suggestion[] = [];
  for (const option of ranked) {
    // One suggestion per day, so the three choices are real alternatives.
    if (picked.some((item) => item.day === option.day)) continue;
    picked.push(option);
    if (picked.length === 3) break;
  }
  return picked.map((option, index) => ({
    ...option,
    reason:
      option.conflicts.length > 0
        ? `No clear ${reading.part === "any" ? "time" : reading.part} is left, so someone would need to move`
        : index === 0
          ? "Everyone is free and it is the earliest clear slot"
          : "Everyone is free, with a gap before and after",
  }));
}

