const BASE = Date.UTC(2026, 10, 9);
const SHORT = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
const WEEKDAY = new Intl.DateTimeFormat("en-US", { weekday: "short", timeZone: "UTC" });
const LONG = new Intl.DateTimeFormat("en-US", { weekday: "long", month: "short", day: "numeric", timeZone: "UTC" });
const TIME = new Intl.DateTimeFormat("en-US", { hour: "numeric", minute: "2-digit", timeZone: "UTC" });

const dateOf = (day: number) => new Date(BASE + day * 86_400_000);

/** A short date for a day number, such as Nov 11. */
export const shortDate = (day: number) => SHORT.format(dateOf(day));

/** A short weekday for a day number, such as Wed. */
export const weekdayName = (day: number) => WEEKDAY.format(dateOf(day));

/** A long date for a day number, such as Wednesday, Nov 11. */
export const longDate = (day: number) => LONG.format(dateOf(day));

/** The day of the month for a day number. */
export const dayOfMonth = (day: number) => dateOf(day).getUTCDate();

/** A time such as 9:30 AM, from minutes after midnight. */
export const clock = (minutes: number) => TIME.format(new Date(BASE + minutes * 60_000));

/** The Monday on or before a day number. Day 0 is a Monday. */
export const mondayOf = (day: number) => day - (((day % 7) + 7) % 7);

/** Rounds minutes to the nearest step. */
export const snap = (minutes: number, step: number) => Math.round(minutes / step) * step;

/** Where an event sits beside the events it overlaps: its lane and how many lanes its group needs. */
export interface Placed {
  event: TimedEvent;
  lane: number;
  lanes: number;
}

/**
 * Places one day's events side by side where they overlap. Events that touch
 * a chain of overlaps share one group, and each takes the first free lane.
 */
export function placeDay(events: TimedEvent[]): Placed[] {
  const sorted = [...events].sort((a, b) => a.start - b.start || b.end - a.end);
  const placed: Placed[] = [];
  let group: Placed[] = [];
  let groupEnd = -1;

  const close = () => {
    const lanes = Math.max(1, ...group.map((item) => item.lane + 1));
    for (const item of group) item.lanes = lanes;
    placed.push(...group);
    group = [];
  };

  for (const event of sorted) {
    if (group.length > 0 && event.start >= groupEnd) close();
    const taken = new Set(group.filter((item) => item.event.end > event.start).map((item) => item.lane));
    let lane = 0;
    while (taken.has(lane)) lane += 1;
    group.push({ event, lane, lanes: 1 });
    groupEnd = Math.max(groupEnd, event.end);
  }
  if (group.length > 0) close();
  return placed;
}

