/**
 * Three ranked times as a radio group. The top one is marked best, each one
 * gives its reason, and a time that clashes says with whom. Up and down move
 * between them and Enter opens the draft invite.
 */
export function SuggestionList({ suggestions, days, selected, onSelect, onPick }: SuggestionListProps) {
  const reduceMotion = useReducedMotion();
  const roving = useRoving(suggestions.length, selected, onSelect);
  const highlightId = useId();
  return (
    <div role="radiogroup" aria-label="Suggested times" className="flex flex-col gap-1">
      {suggestions.map((item, index) => {
        const checked = index === selected;
        const { onKeyDown, ...rest } = roving.itemProps(index);
        return (
          <div
            key={`${item.day}-${item.start}`}
            role="radio"
            aria-checked={checked}
            onClick={() => onSelect(index)}
            onKeyDown={(event) => {
              if (event.key === "Enter" || event.key === " ") {
                event.preventDefault();
                if (event.key === "Enter") onPick(index);
                else onSelect(index);
                return;
              }
              onKeyDown(event);
            }}
            {...rest}
            className="group relative isolate flex cursor-pointer flex-col gap-1 rounded-xl px-3 py-2.5 outline-none focus-visible:ring-2 focus-visible:ring-ring"
          >
            {checked ? (
              <motion.span
                layoutId={highlightId}
                aria-hidden="true"
                transition={reduceMotion ? { duration: 0 } : { type: "spring", stiffness: 400, damping: 40 }}
                className="absolute inset-0 -z-10 rounded-xl border border-chart-1 bg-muted/50"
              />
            ) : null}
            <span className="flex flex-wrap items-center gap-2 text-sm font-medium">
              {days[item.day]}, {clock(item.start)} to {clock(item.end)}
