              <span className={cn("flex items-center gap-1.5 text-xs", STATUS_TEXT.watch)}>
                <AlertTriangleIcon aria-hidden="true" className="size-3.5" />
                {item.conflicts.map((conflict) => `${person(conflict.id).name.split(" ")[0]} has ${conflict.what.toLowerCase()}`).join(", ")}
              </span>
            ) : null}
          </div>
        );
      })}
    </div>
  );
}

